```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();

        while (q-- > 0) {
            int m = Integer.parseInt(br.readLine().trim());
            long[] a = new long[m];
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 0; i < m; i++) {
                a[i] = Long.parseLong(st.nextToken());
            }

            int[] L = new int[m];
            int[] R = new int[m];

            // 从左到右扫描，维护前缀最大值及其最右位置
            long mx = -1;
            int pos = -1;
            for (int i = 0; i < m; i++) {
                L[i] = pos;
                if (a[i] > mx) {
                    mx = a[i];
                    pos = i;
                } else if (a[i] == mx) {
                    pos = i;
                }
            }

            // 从右到左扫描，维护后缀最大值及其最左位置
            mx = -1;
            pos = -1;
            for (int i = m - 1; i >= 0; i--) {
                R[i] = pos;
                if (a[i] > mx) {
                    mx = a[i];
                    pos = i;
                } else if (a[i] == mx) {
                    pos = i;
                }
            }

            int ans = 0;
            for (int p = 1; p + 1 < m; p++) {
                if (p - L[p] == R[p] - p) {
                    ans++;
                }
            }
            sb.append(ans).append('\n');
        }
        System.out.print(sb);
    }
}
